/* بيانات باب taqwa: تُحمَّل عند أول فتح للقسم */
window.TAQWA = {"ch":[{"id":"ma3na","t":"معنى التقوى وحقيقتها","d":"الآيات التي بيّنت ما التقوى وكيف تُؤدّى حقّ أدائها، وأين محلّها من الإنسان، وبماذا يتفاضل الناس عند الله."},{"id":"sifat","t":"صفات المتقين","d":"الآيات التي وصفت المتقين بما يعتقدونه ويعملونه، وأعدّ الله لهم الجنة."},{"id":"thamar","t":"ثمرات التقوى","d":"ما رتّبه الله على التقوى من خير الدنيا والآخرة: الفرقان والمخرج والتيسير والبركة والولاية والمعية والعاقبة."},{"id":"asbab","t":"أسباب التقوى ومعيناتها","d":"الأعمال والأحوال التي ذكرت الآيات أنها تُورث التقوى أو تقرّب منها: الصيام والعبادة والقرآن وصحبة الصادقين والصبر ومحاسبة النفس."},{"id":"mumin","t":"صفات المؤمنين","d":"الآيات التي وصف الله بها المؤمنين: وجل القلب والخشوع والصدق والوفاء والقيام بالليل والرحمة والإنفاق وعباد الرحمن."}],"tp":[{"id":"haqq","ch":"ma3na","t":"«اتقوا الله حق تقاته»","e":"الأمر بتقوى الله حقّ تقاته، وبيان ما قاله الصحابة في معنى ذلك.","ay":[[3,102,102]],"q":[{"bk":"saadi","s":3,"ay":102,"x":"هذه الآيات فيها حث الله عباده المؤمنين أن يقوموا بشكر نعمه العظيمة بأن يتقوه حق تقواه، وأن يقوموا بطاعته وترك معصيته مخلصين له بذلك، وأن يقيموا دينهم ويستمسكوا بحبله الذي أوصله إليهم، وجعله السبب بينهم وبينه وهو دينه وكتابه، والاجتماع على ذلك وعدم التفرق، وأن يستديموا ذلك إلى الممات.","w":"السعدي","en":"Al-Sa'di: these verses urge the believing servants to give thanks for Allah's great favours by fearing Him as He deserves, obeying Him and leaving disobedience sincerely, establishing their religion and holding to His rope, which is His religion and His Book, being united on it without splitting, and continuing so until death."},{"bk":"ibnkathir","s":3,"ay":102,"x":"عَنْ عَبْدِ اللَّهِ -هُوَ ابْنُ مَسْعُودٍ- ﴿اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ﴾ قَالَ: أَنْ يُطاع فَلَا يُعْصَى، وَأَنْ يُذْكَر فَلَا يُنْسَى، وَأَنْ يُشْكَر فَلَا يُكْفَر .","w":"ابن كثير","en":"Ibn Kathir: through his chain, Abdullah ibn Mas'ud said about 'Fear Allah as He should be feared': that He be obeyed and not disobeyed, remembered and not forgotten, and thanked and not denied."}]},{"id":"istata","ch":"ma3na","t":"«فاتقوا الله ما استطعتم»","e":"تقييد التقوى بالاستطاعة، وأن ما عجز عنه العبد يسقط عنه.","ay":[[64,16,16]],"q":[{"bk":"saadi","s":64,"ay":16,"x":"يأمر تعالى بتقواه التي هي امتثالُ أوامره واجتنابُ نواهيه، وقيَّد ذلك بالاستطاعة والقدرة. فهذه الآية تدلُّ على أنَّ كلَّ واجبٍ عجز عنه العبد يسقُطُ عنه، وأنَّه إذا قدر على بعض المأمور وعجز عن بعضه؛ فإنَّه يأتي بما يقدر عليه ويسقُطُ عنه ما يعجزُ عنه؛ كما قال النبيُّ - صلى الله عليه وسلم -: «إذا أمرتُكم بأمرٍ؛ فأتوا منه ما استطعتُم ».","w":"السعدي","en":"Al-Sa'di: Allah commands fearing Him, which is following His commands and avoiding His prohibitions, and limits it by ability and capacity; so any obligation a servant cannot do falls from him, and if he can do part of what is commanded and not another part, he does what he can and the rest falls away, as the Prophet said: 'When I command you to do something, do of it what you are able.'"}]},{"id":"zad","ch":"ma3na","t":"«وتزودوا فإن خير الزاد التقوى»","e":"الأمر بالتزود لسفر الحج، وأن خير الزاد التقوى.","ay":[[2,197,197]],"q":[{"bk":"saadi","s":2,"ay":197,"x":"وهذا الزاد الذي المراد منه إقامة البِنْية بُلْغَةٌ ومتاع، وأما الزاد الحقيقي المستمر نفعه لصاحبه في دنياه وأخراه فهو زاد التقوى …","w":"السعدي","en":"Al-Sa'di: what is meant by provision here, to keep the body going, is only sustenance and enjoyment; the real provision whose benefit lasts for its owner in this world and the next is the provision of taqwa, which is a provision to the lasting home …"},{"bk":"qurtubi","s":2,"ay":197,"x":"الثَّالِثَةَ عَشْرَةَ- قَوْلُهُ تَعَالَى: ﴿فَإِنَّ خَيْرَ الزَّادِ التَّقْوى ﴾ أَخْبَرَ تَعَالَى أَنَّ خَيْرَ الزَّادِ اتِّقَاءُ الْمَنْهِيَّاتِ، فَأَمَرَهُمْ أَنْ يَضُمُّوا إِلَى التَّزَوُّدِ التَّقْوَى.","w":"القرطبي","en":"Al-Qurtubi: He says that the best provision is guarding against what is forbidden, so He told them to join taqwa to taking provision."},{"bk":"qurtubi","s":2,"ay":197,"x":"قَالَ أَهْلُ الْإِشَارَاتِ: ذَكَّرَهُمُ اللَّهُ تَعَالَى سَفَرَ الْآخِرَةِ وَحَثَّهُمْ عَلَى تَزَوُّدِ التَّقْوَى، فَإِنَّ التَّقْوَى زَادُ الْآخِرَةِ.","w":"القرطبي","en":"Al-Qurtubi: the people of spiritual allusions said: Allah reminded them of the journey to the Hereafter and urged them to take the provision of taqwa, for taqwa is the provision of the Hereafter."}]},{"id":"libas","ch":"ma3na","t":"«ولباس التقوى ذلك خير»","e":"امتنان الله باللباس، ووصف لباس التقوى بأنه خير.","ay":[[7,26,26]],"q":[{"bk":"saadi","s":7,"ay":26,"x":"ثم امتنَّ عليهم بما يسَّر لهم من اللباس الضروري واللباس الذي المقصود منه الجمال، وهكذا سائر الأشياء كالطعام والشراب والمراكب والمناكح، ونحوها قد يسر الله للعباد ضروريَّها ومكمِّل ذلك، وبيَّن لهم أن هذا ليس مقصوداً بالذات، وإنَّما أنزله الله ليكون معونةً لهم على عبادته وطاعته، ولهذا قال:{ولباسُ التَّقوى ذلك خيرٌ}: من اللباس الحسيِّ؛ فإن لباس التقوى يستمرُّ مع العبد ولا يبلى ولا يبيد، وهو جمال القلب والروح، وأما اللباس الظاهريُّ؛ فغايتُه أن يستُر العورة الظاهرة في وقت من الأوقات، أو يكون جمالاً للإنسان، وليس وراء ذلك منه نفع.","w":"السعدي","en":"Al-Sa'di: Allah reminds them of the necessary clothing and the clothing meant for beauty, and says it is not the goal itself but sent down to help them worship and obey Him; 'the garment of taqwa, that is best' is better than physical clothing, for the garment of taqwa stays with a servant and never wears out, and is the beauty of heart and spirit, while outer clothing at most covers the body for a time or adorns a person, and no benefit lies beyond that."}]},{"id":"qulub","ch":"ma3na","t":"التقوى محلها القلوب","e":"تعظيم الشعائر من تقوى القلوب، وأن الذي يبلغ الله هو التقوى لا اللحوم والدماء.","ay":[[22,32,32],[22,37,37]],"q":[{"bk":"saadi","s":22,"ay":32,"x":"فتعظيمُ شعائِر الله صادرٌ من تَقْوى القلوب؛ فالمعظِّم لها يبرهِنُ على تقواه وصحَّة إيمانِهِ؛ لأنَّ تعظيمها تابعٌ لتعظيم الله وإجلاله.","w":"السعدي","en":"Al-Sa'di: honouring Allah's rites comes from the taqwa of hearts; whoever honours them proves his taqwa and the soundness of his faith, since honouring them follows honouring and exalting Allah."},{"bk":"saadi","s":22,"ay":37,"x":"وقوله: {لن ينالَ اللهَ لحومُها ولا دِماؤها}؛ أي: ليس المقصود منها ذبحها فقط، ولا ينالُ اللهَ من لحومها ولا دمائها شيءٌ؛ لكونه الغنيَّ الحميد، وإنَّما ينالُه الإخلاصُ فيها والاحتسابُ والنيَّة الصالحةُ، ولهذا قال:{ولكن ينالُهُ التَّقوى منكم}: ففي هذا حثٌّ وترغيبٌ على الإخلاص في النحر، وأن يكونَ القصدُ وجهَ الله وحدَه؛ لا فخراً ولا رياءً ولا سمعةً ولا مجرَّد عادةٍ، وهكذا سائر العبادات إن لم يقترِنْ بها الإخلاص وتقوى الله؛ كانتْ كالقُشورِ الذي لا لبَّ فيه والجسدِ الذي لا روح فيه.","w":"السعدي","en":"Al-Sa'di: 'Neither their flesh nor their blood reaches Allah', meaning slaughter alone is not the aim and nothing of the flesh or blood reaches Allah, who is the Self-Sufficient, the Praiseworthy; what reaches Him is sincerity in it, seeking His reward and a good intention, 'but taqwa from you reaches Him'; this urges sincerity in sacrifice, that the aim be Allah's face alone, not pride, show, fame or mere habit; and so with all acts of worship: without sincerity and taqwa they are like husks with no kernel and a body with no spirit."}]},{"id":"karam","ch":"ma3na","t":"«إن أكرمكم عند الله أتقاكم»","e":"بيان أن التفاضل عند الله بالتقوى لا بالنسب.","ay":[[49,13,13]],"q":[{"bk":"ibnkathir","s":49,"ay":13,"x":"وَقَوْلُهُ: ﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ﴾ أَيْ: إِنَّمَا تَتَفَاضَلُونَ عِنْدَ اللَّهِ بِالتَّقْوَى لَا بِالْأَحْسَابِ.","w":"ابن كثير","en":"Ibn Kathir: His words 'the most honoured of you before Allah is the most mindful of you' mean that you are ranked before Allah by taqwa and not by lineage."}]},{"id":"imtihan","ch":"ma3na","t":"القلوب الممتحنة للتقوى","e":"مدح الذين يغضّون أصواتهم عند رسول الله، وأن الله امتحن قلوبهم للتقوى.","ay":[[49,3,3]],"q":[{"bk":"saadi","s":49,"ay":3,"x":"ثم مدح من غضَّ صوته عند رسول الله - صلى الله عليه وسلم - بأنَّ الله امتحن قلوبَهم للتقوى؛ أي: ابتلاها واختبرها، فظهرت نتيجةُ ذلك بأن صَلَحَت قلوبهم للتقوى.","w":"السعدي","en":"Al-Sa'di: then He praises those who lower their voices before the Messenger of Allah, saying that Allah has tested their hearts for taqwa, meaning He tried them and examined them, and the result was that their hearts became fit for taqwa."}]},{"id":"qawl","ch":"ma3na","t":"التقوى والقول السديد","e":"الأمر بالتقوى مع القول السديد وما يترتب عليهما من صلاح الأعمال ومغفرة الذنوب.","ay":[[33,70,71]],"q":[{"bk":"saadi","s":33,"ay":70,"x":"يأمر تعالى المؤمنين بتقواه في جميع أحوالِهِم في السرِّ والعلانية، ويخصُّ منها ويندب للقول السديد، وهو القول الموافق للصواب أو المقارب له عند تعذُّر اليقين من قراءةٍ وذكرٍ وأمرٍ بمعروف ونهي عن منكر وتعلُّم علم وتعليمه والحرص على إصابة الصواب في المسائل العلميَّة وسلوك كلِّ طريق موصِل لذلك وكل وسيلةٍ تُعين عليه. ومن القول السديد لينُ الكلام ولطفُه في مخاطبة الأنام والقول المتضمِّن للنُّصح والإشارة بما هو الأصلح.","w":"السعدي","en":"Al-Sa'di: Allah commands the believers to fear Him in all their states, in private and in public, and singles out and urges straight speech, which is speech that matches the truth or comes close to it when certainty is not possible, in reciting, remembering, enjoining good and forbidding evil, learning and teaching knowledge, striving to be right in questions of knowledge and following every path and means that helps it. Among straight speech is gentleness and kindness in addressing people and speech that holds sincere advice and pointing to what is best."}]},{"id":"wassa","ch":"ma3na","t":"وصية الله للأولين والآخرين","e":"أن التقوى وصية الله للأمم السابقة ولهذه الأمة.","ay":[[4,131,131]],"q":[{"bk":"ibnkathir","s":4,"ay":131,"x":"يُخْبِرُ تَعَالَى أَنَّهُ مَالِكُ السَّمَاوَاتِ وَالْأَرْضِ، وَأَنَّهُ الْحَاكِمُ فِيهِمَا؛ وَلِهَذَا قَالَ: ﴿وَلَقَدْ وَصَّيْنَا الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَإِيَّاكُمْ﴾ أَيْ: وَصَّيْنَاكُمْ بِمَا وَصَّيْنَاهُمْ بِهِ، مِنْ تَقْوَى اللَّهِ، عَزَّ وَجَلَّ، بِعِبَادَتِهِ وَحْدَهُ لَا شَرِيكَ لَهُ.","w":"ابن كثير","en":"Ibn Kathir: Allah tells that He owns the heavens and the earth and rules over them; so He said 'We have counselled those given the Book before you, and you', meaning We counselled you with what We counselled them: taqwa of Allah, the Mighty and Majestic, by worshipping Him alone with no partner."}]},{"id":"baqara","ch":"sifat","t":"«هدى للمتقين»: أول من ذُكروا في المصحف","e":"أن القرآن هدى للمتقين، وبداية وصفهم بعقائدهم وأعمالهم.","ay":[[2,2,5]],"q":[{"bk":"saadi","s":2,"ay":2,"x":"وأما المتقون الذين أتوا بالسبب الأكبر لحصول الهداية وهو التقوى التي حقيقتها: اتخاذ ما يقي سخط الله وعذابه بامتثال أوامره، واجتناب النواهي، فاهتدوا به، وانتفعوا غاية الانتفاع، قال تعالى:{يا أيها الذين آمنوا إن تتقوا الله يجعل لكم فرقاناً} فالمتقون هم المنتفعون بالآيات القرآنية والآيات الكونية.","w":"السعدي","en":"Al-Sa'di: as for the people of taqwa, who brought the greatest means to receive guidance, which is taqwa, whose reality is taking what protects from Allah's anger and punishment by following His commands and avoiding His prohibitions: they were guided by it and benefited fully, as He said: 'If you fear Allah, He will give you a criterion'; so the people of taqwa are those who benefit from the verses of the Quran and the verses of the universe."},{"bk":"saadi","s":2,"ay":2,"x":"ثم وصف المتقين بالعقائد والأعمال الباطنة والأعمال الظاهرة لتضمن التقوى لذلك فقال: {3}{الذين يؤمنون بالغيب} حقيقة الإيمان هو التصديق التام بما أخبرت به الرسل، المتضمن لانقياد الجوارح، وليس الشأن في الإيمان بالأشياء المشاهدة بالحسِّ، فإنه لا يتميز بها المسلم من الكافر، إنما الشأنُ في الإيمان بالغيب الذي لم نره ولم نشاهده، وإنما نؤمن به لخبر الله وخبر رسوله.","w":"السعدي","en":"Al-Sa'di: then He describes the people of taqwa by inner beliefs, inner deeds and outer deeds, because taqwa includes all of that: 'who believe in the unseen'; the reality of faith is complete acceptance of what the messengers reported, which includes the limbs' submission; the matter is not belief in things seen by the senses, by which a Muslim is not set apart from a disbeliever, but belief in the unseen that we have not seen or witnessed and believe only because Allah and His Messenger told us."}]},{"id":"birr","ch":"sifat","t":"«ليس البر… ولكن البر من آمن بالله»","e":"وصف البرّ بالإيمان والإنفاق والصلاة والوفاء والصبر، ووصف أهله بالصدق والتقوى.","ay":[[2,177,177]],"q":[{"bk":"saadi","s":2,"ay":177,"x":"أي: المتصفون بما ذكر من العقائد الحسنة والأعمال التي هي آثار الإيمان وبرهانه ونوره والأخلاق التي هي جمال الإنسان وحقيقة الإنسانية فأولئك {الذين صدقوا}؛ في إيمانهم لأن أعمالهم صدقت إيمانهم {وأولئك هم المتقون}؛ لأنهم تركوا المحظور وفعلوا المأمور، لأن هذه الأمور مشتملة على كل خصال الخير تضمناً ولزوماً لأن الوفاء بالعهد يدخل فيه الدين كله، ولأن العبادات المنصوص عليها في هذه الآية أكبر العبادات، ومن قام بها كان بما سواها أقوم، فهؤلاء [هم] الأبرار الصادقون المتقون …","w":"السعدي","en":"Al-Sa'di: 'those' are the ones described with the good beliefs and deeds that are the marks of faith, its proof and light, and the morals that are human beauty and the reality of humanity, so they are 'the ones who were truthful' in their faith because their deeds proved their faith, 'and those are the muttaqin' because they left what is forbidden and did what is commanded; for these matters hold every good quality by implication, since keeping a pledge includes the whole religion, and the acts of worship named in the verse are the greatest, and whoever does them is more firmly upright in all else; so these are the righteous, the truthful, the people of taqwa …"},{"bk":"ibnkathir","s":2,"ay":177,"x":"وَقَوْلُهُ: ﴿أُولَئِكَ الَّذِينَ صَدَقُوا﴾ أَيْ: هَؤُلَاءِ الَّذِينَ اتَّصَفُوا بِهَذِهِ الصِّفَاتِ هُمُ الَّذِينَ صَدَقوا فِي إِيمَانِهِمْ؛ لِأَنَّهُمْ حَقَّقُوا الْإِيمَانَ الْقَلْبِيَّ بِالْأَقْوَالِ وَالْأَفْعَالِ، فَهَؤُلَاءِ هُمُ الَّذِينَ صَدَقُوا ﴿وَأُولَئِكَ هُمُ الْمُتَّقُونَ﴾ لِأَنَّهُمُ اتَّقَوُا الْمَحَارِمَ وَفَعَلُوا الطَّاعَاتِ.","w":"ابن كثير","en":"Ibn Kathir: 'those are the ones who were truthful' means those who are described with these qualities are truthful in their faith, because they brought faith of the heart to realisation in words and deeds, 'and those are the muttaqin' because they guarded against what is forbidden and did the acts of obedience."}]},{"id":"aal","ch":"sifat","t":"«وسارعوا إلى مغفرة من ربكم… للمتقين»","e":"الجنة التي أُعدّت للمتقين، وصفاتهم: الإنفاق وكظم الغيظ والعفو والإحسان والاستغفار.","ay":[[3,133,136]],"q":[{"bk":"saadi","s":3,"ay":133,"x":"ثم أمرهم تعالى بالمسارعة إلى مغفرته وإدراك جنته التي عرضها السماوات والأرض، فكيف بطولها التي أعدها الله للمتقين؟! فهم أهلها وأعمال التقوى هي الموصلة إليها.","w":"السعدي","en":"Al-Sa'di: then He commands them to hasten to His forgiveness and reach His Garden, whose width is the heavens and the earth, so how about its length, which Allah has prepared for the muttaqin; they are its people, and deeds of taqwa are what lead to it."},{"bk":"saadi","s":3,"ay":134,"x":"ثم وصف المتقين وأعمالهم فقال: {الذين ينفقون في السراء والضراء}؛ أي: في حال عسرهم ويسرهم إن أيسروا أكثروا من النفقة وإن أعسروا لم يحتقروا من المعروف شيئاً ولو قل، {والكاظمين الغيظ}: أي: إذا حصل لهم من غيرهم أذية توجب غيظهم، وهو امتلاء قلوبهم من الحنق الموجب للانتقام بالقول والفعل.","w":"السعدي","en":"Al-Sa'di: then He describes the muttaqin and their deeds: 'those who spend in ease and hardship', meaning in their times of difficulty and of ease, giving much when well off and, when hard-pressed, not despising any good, however small; 'and those who restrain anger', that is, when others hurt them in a way that stirs anger, which is the heart filling with rage that calls for revenge in word and deed."}]},{"id":"dhariyat","ch":"sifat","t":"المتقون في جنات: كانوا قليلاً من الليل ما يهجعون","e":"جزاء المتقين في الجنات وعيونها، وأعمالهم في الدنيا من إحسان وقيام بالليل واستغفار.","ay":[[51,15,19]],"q":[{"bk":"saadi","s":51,"ay":15,"x":"يقول تعالى في ذكر ثواب المتَّقين وأعمالهم التي وصلوا بها إلى ذلك الجزاء: {إنَّ المتَّقينَ}؛ أي: الذين كانت التَّقوى شعارهم وطاعةُ اللهِ دثارهم …","w":"السعدي","en":"Al-Sa'di: Allah tells of the reward of the muttaqin and the deeds that brought them to it: 'the muttaqin', those for whom taqwa was their outer garment and obedience to Allah their inner garment, 'will be among gardens' …"}]},{"id":"sidq","ch":"sifat","t":"«والذي جاء بالصدق وصدق به أولئك هم المتقون»","e":"وصف الذي جاء بالصدق وصدّق به بأنه من المتقين.","ay":[[39,33,33]],"q":[{"bk":"saadi","s":39,"ay":33,"x":"أي: الذين وُفِّقوا للجمع بين الأمرين {هم المتَّقونَ}: فإنَّ جميع خصال التقوى ترجِعُ إلى الصدق بالحقِّ والتصديق به.","w":"السعدي","en":"Al-Sa'di: meaning those who were granted success to combine the two matters, 'they are the muttaqin', for all the qualities of taqwa go back to truthfulness with the truth and belief in it."}]},{"id":"furqan","ch":"thamar","t":"الفرقان وتكفير السيئات","e":"ما وعد الله به أهل التقوى: الفرقان وتكفير السيئات والمغفرة.","ay":[[8,29,29]],"q":[{"bk":"saadi","s":8,"ay":29,"x":"امتثالُ العبد لتقوى ربه عنوان السعادة وعلامة الفلاح، وقد رتَّب اللَّه على التقوى من خير الدنيا والآخرة شيئاً كثيراً، فذكر هنا أنَّ مَن اتَّقى اللَّه؛ حصل له أربعةُ أشياء، كلُّ واحدٍ منها خيرٌ من الدنيا وما فيها: الأول: الفُرقان، وهو العلم والهدى الذي يفرِّق به صاحبه بين الهدى والضلال والحقِّ والباطل والحلال والحرام وأهل السعادة من أهل الشقاوة. الثاني والثالث: تكفير السيئات ومغفرة الذنوب، وكل واحد منهما داخلٌ في الآخر عند الإطلاق، وعند الاجتماع يفسَّر تكفير السيئات بالذُّنوب الصغائر، ومغفرة الذنوب بتكفير الكبائر.","w":"السعدي","en":"Al-Sa'di: a servant's compliance with taqwa of his Lord is the sign of happiness and success, and Allah has attached to taqwa a great deal of good of this world and the next; here He mentions that whoever fears Allah gets four things, each better than the world and what is in it: first, the criterion, which is knowledge and guidance by which its owner tells guidance from error, truth from falsehood, lawful from unlawful and the people of happiness from the people of misery; second and third, the wiping away of evil deeds and the forgiveness of sins, each included in the other when mentioned alone, and when joined the wiping away is explained as minor sins and forgiveness as covering the major ones."}]},{"id":"makhraj","ch":"thamar","t":"«ومن يتق الله يجعل له مخرجاً»","e":"وعد من اتقى الله بمخرج ورزق من حيث لا يحتسب.","ay":[[65,2,3]],"q":[{"bk":"saadi","s":65,"ay":3,"x":"ولما كان الطلاق قد يوقع في الضيق والكرب والغمِّ؛ أمر تعالى بتقواه، ووعد مَنْ اتَّقاه في الطلاق وغيره بأن يجعل له فرجاً ومخرجاً.","w":"السعدي","en":"Al-Sa'di: since divorce can bring distress, hardship and grief, Allah commands taqwa of Him and promises whoever fears Him in divorce and otherwise that He will make for him relief and a way out."},{"bk":"ibnkathir","s":65,"ay":3,"x":"وَقَوْلُهُ: ﴿وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ﴾ أَيْ: وَمَنْ يَتَّقِ اللَّهَ فِيمَا أَمَرَهُ بِهِ، وتَرَك مَا نَهَاهُ عَنْهُ، يَجْعَلْ لَهُ مِنْ أَمْرِهِ مَخْرَجًا، وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ، أَيْ: مِنْ جِهَةٍ لَا تَخْطُرُ بِبَالِهِ.","w":"ابن كثير","en":"Ibn Kathir: 'whoever fears Allah, He makes a way out for him and provides for him from where he does not expect' means whoever fears Allah in what He has commanded and leaves what He has forbidden, Allah makes for him a way out of his affair and provides for him from where it never crosses his mind."}]},{"id":"yusr","ch":"thamar","t":"التيسير وتكفير السيئات وعظم الأجر","e":"وعد المتقي بتيسير أمره وتكفير سيئاته وعظم أجره.","ay":[[65,4,5]],"q":[{"bk":"saadi","s":65,"ay":4,"x":"أي: من اتَّقى الله يَسَّرَ له الأمور، وسهَّل عليه كلَّ عسير.","w":"السعدي","en":"Al-Sa'di: whoever fears Allah, He makes things easy for him and eases every difficulty for him."},{"bk":"saadi","s":65,"ay":5,"x":"{ذلك}؛ أي: الحكم الذي بيَّنه الله لكم {أمرُ الله أنزلَه إليكم}: لتمشوا عليه وتأتمُّوا به وتُعظموه. {ومَن يتَّقِ الله يُكَفِّرۡ عنه سيئاتِهِ ويُعۡظِمۡ له أجراً}؛ أي: يندفع عنه المحذور ويحصل له المطلوب.","w":"السعدي","en":"Al-Sa'di: 'that is the command of Allah, which He has sent down to you', so that you walk by it, follow it and honour it; 'and whoever fears Allah, He will wipe away his evil deeds and make his reward great', meaning what he fears is turned away from him and what he seeks is attained."}]},{"id":"baraka","ch":"thamar","t":"بركات السماء والأرض","e":"أن أهل القرى لو آمنوا واتقوا لفتح الله عليهم بركات السماء والأرض.","ay":[[7,96,96]],"q":[{"bk":"saadi","s":7,"ay":96,"x":"ذكر أنَّ أهل القُرى لو آمنوا بقلوبهم إيماناً صادقاً صدقتْه الأعمالُ، واستعملوا تقوى الله تعالى ظاهراً وباطناً بترك جميع ما حرَّم الله [تعالى]؛ لفتحَ عليهم بركاتِ السَّماء والأرض، فأرسل السماء عليهم مدراراً، وأنبتَ لهم من الأرض ما به يعيشون وتعيشُ بهائمهُم في أخصب عيش وأغزر رزق من غير عناء ولا تعبٍ ولا كدٍّ ولا نصبٍ …","w":"السعدي","en":"Al-Sa'di: Allah mentions that if the people of the towns had believed in their hearts with sincere faith confirmed by deeds, and used taqwa of Allah outwardly and inwardly by leaving all that He forbade, He would have opened to them blessings of heaven and earth, sending rain upon them in plenty and growing for them from the earth what they and their animals live on, in the richest living and widest provision, without toil, fatigue, hardship or strain …"}]},{"id":"wilaya","ch":"thamar","t":"أولياء الله: الذين آمنوا وكانوا يتقون","e":"وصف أولياء الله بالإيمان والتقوى، وبشراهم في الدنيا والآخرة.","ay":[[10,62,64]],"q":[{"bk":"saadi","s":10,"ay":63,"x":"ثم ذكر وصفَهم، فقال:{الذين آمنوا}: بالله وملائكته وكتبه ورسله واليوم الآخر وبالقدر خيره وشرِّه، وصدَّقوا إيمانهم باستعمال التقوى بامتثال الأوامر واجتناب النواهي؛ فكلُّ من كان مؤمناً تقيًّا؛ كان لله تعالى وليًّا.","w":"السعدي","en":"Al-Sa'di: then He mentions their description: 'those who believe', in Allah, His angels, books, messengers, the Last Day and destiny, good and bad, and made their faith true by practising taqwa, following the commands and avoiding the prohibitions; so everyone who is a believer with taqwa is a friend of Allah."},{"bk":"saadi","s":10,"ay":64,"x":"و {لهم البُشرى في الحياة الدنيا وفي الآخرة}: أما البشارة في الدُّنيا؛ فهي الثناء الحسن والمودَّة في قلوب المؤمنين والرؤيا الصالحة وما يراه العبد من لطف الله به وتيسيره لأحسن الأعمال والأخلاق وصرفه عن مساوئ الأخلاق …","w":"السعدي","en":"Al-Sa'di: 'theirs are glad tidings in the life of this world and in the Hereafter'; as for the good news in this world, it is the good reputation, the love in believers' hearts, the true dream, and what a servant sees of Allah's gentleness toward him, His easing him to the best deeds and manners and turning him from bad manners …"}]},{"id":"maiyya","ch":"thamar","t":"معية الله للمتقين ومحبته لهم","e":"معية الله للمتقين المحسنين ومحبته لمن أوفى بعهده واتقى.","ay":[[16,128,128],[3,76,76]],"q":[{"bk":"saadi","s":16,"ay":128,"x":"فإنَّ مكرهم عائدٌ إليهم، وأنت من المتَّقين المحسنين، والله مع المتقين المحسنين بعونه وتوفيقه وتسديده، وهم الذين اتَّقوا الكفر والمعاصي، وأحسنوا في عبادة الله؛ بأن عبدوا الله كأنَّهم يرونَه؛ فإنْ لَم يكُونوا يَرَوْنه فإنَّه يراهم، والإحسان إلى الخلق ببذل النفع لهم من كل وجه. نسأل الله أن يَجْعَلَنا من المتقين المحسنين.","w":"السعدي","en":"Al-Sa'di: their scheming rebounds on them, and you are among the muttaqin who do good, and Allah is with the muttaqin who do good with His help, success and guidance; they are those who guarded against disbelief and sins and did good in worship of Allah by worshipping Him as if they see Him, and if they do not see Him, He sees them, and in doing good to people by giving them benefit in every way. We ask Allah to make us among the muttaqin who do good."},{"bk":"saadi","s":3,"ay":76,"x":"أي: قام بحقوق الله وحقوق خلقه فإن هذا هو المتقي والله يحبه، أي: ومن كان بخلاف ذلك فلم يف بعهده وعقوده التي بينه وبين الخلق ولا قام بتقوى الله، فإن الله يمقته، وسيجازيه على ذلك أعظم النكال.","w":"السعدي","en":"Al-Sa'di: meaning one who fulfils the rights of Allah and the rights of His creation: this one is the muttaqi and Allah loves him; and whoever is the opposite, not keeping his pledges and contracts between him and people, nor holding taqwa of Allah, Allah hates him and will repay him for that with the greatest punishment."}]},{"id":"aqiba","ch":"thamar","t":"«والعاقبة للمتقين»","e":"أن الدار الآخرة للذين لا يريدون علواً في الأرض، وأن العاقبة للمتقين.","ay":[[28,83,83],[7,128,128]],"q":[{"bk":"saadi","s":28,"ay":83,"x":"لما ذَكَرَ تعالى قارونَ وما أوتيه من الدُّنيا وما صارتْ إليه عاقبةُ أمره، وأنَّ أهل العلم قالوا: ثوابُ الله خيرٌ لمن آمنَ وعمل صالحاً؛ رغَّب تعالى في الدار الآخرة، وأخبر بالسبب الموصل إليها، فقال:{تلك الدارُ الآخرةُ}: التي أخبر الله بها في كتبِهِ وأخبرت بها رسلُه التي قد جمعت كلَّ نعيم واندفع عنها كلُّ مكدِّر ومنغِّص، {نجعلُها}: داراً وقراراً {للذين لا يريدونَ علوًّا في الأرض ولا فساداً}؛ أي: ليس لهم إرادةٌ؛ فكيف العملُ للعلوِّ في الأرض على عبادِ الله والتكبُّر عليهم وعلى الحقِّ؟!","w":"السعدي","en":"Al-Sa'di: after mentioning Qarun, what he was given of the world and what became of him, and that the people of knowledge said Allah's reward is better for whoever believes and does good, He encourages the Hereafter and tells of the way that leads to it: 'that home of the Hereafter', which Allah told of in His books and His messengers told of, which has gathered every delight and from which every disturbance is removed, 'We make it for those who do not want exaltation on earth or corruption', meaning they have no desire for it; so how could they work to be high over Allah's servants and be arrogant toward them and toward the truth?"}]},{"id":"ilm","ch":"thamar","t":"«واتقوا الله ويعلمكم الله»","e":"اقتران الأمر بالتقوى بوعد التعليم من الله.","ay":[[2,282,282]],"q":[{"bk":"ibnkathir","s":2,"ay":282,"x":"وَقَوْلُهُ: ﴿وَاتَّقُوا اللَّهَ﴾ أَيْ: خَافُوهُ وَرَاقِبُوهُ، وَاتَّبِعُوا أَمْرَهُ وَاتْرُكُوا زَجْرَهُ ﴿وَيُعَلِّمُكُمُ اللهُ﴾ كَقَوْلِهِ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا﴾ [الْأَنْفَالِ: ٢٩] ، وَكَقَوْلِهِ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِنْ رَحْمَتِهِ وَيَجْعَلْ لَكُمْ نُورًا تَمْشُونَ بِهِ﴾ [الْحَدِيدِ: ٢٨] .","w":"ابن كثير","en":"Ibn Kathir: His words 'and fear Allah' mean fear Him, be aware of Him, follow His command and leave what He forbids; 'and Allah teaches you' is like His words 'O you who believe, if you fear Allah, He will give you a criterion' [al-Anfal 29], and His words 'O you who believe, fear Allah and believe in His Messenger; He will give you two portions of His mercy and make for you a light to walk by' [al-Hadid 28]."}]},{"id":"nur","ch":"thamar","t":"نور يُمشى به ومغفرة","e":"وعد المتقين المؤمنين بالرسول بنصيبين من رحمته ونور يمشون به ومغفرة.","ay":[[57,28,28]],"q":[{"bk":"saadi","s":57,"ay":28,"x":"أي: يعطيكم علماً وهدىً ونوراً تمشون به في ظُلُمات الجهل، ويغفر لكم السيئات، {والله ذو الفضل العظيم}: فلا يُسْتَغْرَبُ كثرةُ هذا الثواب على فضل ذي الفضل العظيم، الذي عمَّ فضلُه أهلَ السماواتِ والأرض؛ فلا يخلو مخلوقٌ من فضله طرفةَ عينٍ ولا أقلَّ من ذلك.","w":"السعدي","en":"Al-Sa'di: meaning He gives you knowledge, guidance and a light to walk by in the darknesses of ignorance, and forgives you your sins, 'and Allah is the Possessor of great bounty'; so the abundance of this reward is no wonder given the bounty of the One of great bounty, whose favour covers the people of the heavens and the earth, and no creature is without His favour for the blink of an eye or less."}]},{"id":"qabul","ch":"thamar","t":"«إنما يتقبل الله من المتقين»","e":"أن الله إنما يتقبل من المتقين.","ay":[[5,27,27]],"q":[{"bk":"saadi","s":5,"ay":27,"x":"الابنُ الذي لم يتقبَّل منه للآخر حسداً وبغياً: {لأقۡتُلَنَّكَ} فقال له الآخر مترقِّقاً له في ذلك: {إنَّما يتقبَّلُ الله من المتَّقين}؛ فأيُّ ذنبٍ لي وجناية توجبُ لك أن تقتلني إلا أني اتَّقيت الله تعالى الذي تقواه واجبةٌ عليَّ وعليك وعلى كلِّ أحد.","w":"السعدي","en":"Al-Sa'di: the son whose offering was not accepted had envy and wrongdoing toward the other, who said 'I will kill you'; the other said to him gently 'Allah accepts only from the muttaqin'; what fault or crime of mine requires you to kill me except that I feared Allah, whose taqwa is obligatory on me, on you and on everyone?"}]},{"id":"nasr","ch":"thamar","t":"الصبر والتقوى: «لا يضركم كيدهم شيئاً»","e":"أن الصبر والتقوى يدفعان كيد الأعداء.","ay":[[3,120,120]],"q":[{"bk":"saadi","s":3,"ay":120,"x":"لما بين تعالى شدة عداوتهم، وشرح ما هم عليه من الصفات الخبيثة أمر عباده المؤمنين بالصبر ولزوم التقوى، وأنهم إذا قاموا بذلك فلن يضرهم كيد أعدائهم شيئاً، فإن الله محيط بهم وبأعمالهم وبمكائدهم التي يكيدونكم فيها، وقد وعدكم عند القيام بالتقوى أنهم لا يضرونكم شيئاً فلا تشكوا في حصول ذلك.","w":"السعدي","en":"Al-Sa'di: after explaining the intensity of their enmity and describing their bad qualities, He commands His believing servants to be patient and hold to taqwa, and that if they do this their enemies' plotting will not harm them at all, for Allah surrounds them, their deeds and the plots they plot against you; He has promised that when you hold taqwa they will not harm you at all, so do not doubt that it will happen."}]},{"id":"siyam","ch":"asbab","t":"الصيام: «لعلكم تتقون»","e":"بيان أن حكمة الصيام تحقيق التقوى.","ay":[[2,183,183]],"q":[{"bk":"saadi","s":2,"ay":183,"x":"ثم ذكر تعالى حكمته في مشروعية الصيام فقال:{لعلكم تتقون}؛ فإن الصيام من أكبر أسباب التقوى لأن فيه امتثال أمر الله واجتناب نهيه، فممِّا اشتمل عليه من التقوى أن الصائم يترك ما حرم الله عليه من الأكل والشرب والجماع ونحوها التي تميل إليها نفسه متقرباً بذلك إلى الله راجياً بتركها ثوابه، فهذا من التقوى، ومنها: أن الصائم يدرب نفسه على مراقبة الله تعالى فيترك ما تهوى نفسه مع قدرته عليه لعلمه باطلاع الله عليه …","w":"السعدي","en":"Al-Sa'di: then He mentions the wisdom of prescribing fasting: 'that you may attain taqwa'; fasting is one of the greatest causes of taqwa because it involves following Allah's command and avoiding His prohibition; part of the taqwa in it is that the fasting person leaves what Allah forbade him of eating, drinking and relations, which his soul inclines to, drawing near to Allah and hoping for His reward by leaving them: this is taqwa; and among it is that the fasting person trains himself to be aware of Allah and leaves what he desires despite being able to have it, because he knows Allah is watching him …"}]},{"id":"qisas","ch":"asbab","t":"«ولكم في القصاص حياة… لعلكم تتقون»","e":"حكمة القصاص في حفظ الدماء، وأنها لعل الناس يتقون.","ay":[[2,179,179]],"q":[{"bk":"saadi","s":2,"ay":179,"x":"ثم بين تعالى حكمته العظيمة في مشروعية القصاص فقال: {179}{ولكم في القصاص حياة}؛ أي: تنحقن بذلك الدماء وتنقمع به الأشقياء، لأن من عرف أنه مقتول إذا قتل لا يكاد يصدر منه القتل، وإذا رُئيَ القاتل مقتولاً انذعر بذلك غيره وانزجر، فلو كانت عقوبة القاتل غير القتل لم يحصل انكفاف الشر الذي يحصل بالقتل، وهكذا سائر الحدود الشرعية فيها من النكاية والانزجار ما يدل على حكمة الحكيم الغفار.","w":"السعدي","en":"Al-Sa'di: then Allah explains the great wisdom of prescribing retaliation: 'in retaliation there is life for you', meaning blood is protected and criminals are restrained, because whoever knows he will be killed if he kills hardly commits killing, and when the killer is seen killed, others take fright and stop; had the killer's penalty been anything else, the restraint of evil that comes by killing would not have come about; and so with all the legal penalties, in which there is deterrence that shows the wisdom of the All-Wise, the Forgiving."}]},{"id":"ibada","ch":"asbab","t":"العبادة: «اعبدوا ربكم… لعلكم تتقون»","e":"الأمر العام بعبادة الله، وأن غايتها أن يتقي الناس.","ay":[[2,21,21]],"q":[{"bk":"saadi","s":2,"ay":21,"x":"هذا أمر عام لجميع الناس بأمر عام وهو العبادة الجامعة لامتثال أوامر الله واجتناب نواهيه وتصديق خبره، فأمرهم تعالى بما خلقهم له، قال تعالى:{وما خلقت الجن والإنس إلا ليعبدون}؛ ثم استدل على وجوب عبادته وحده بأنه ربكم الذي رباكم بأصناف النعم، فخلقكم بعد العدم، وخلق الذين من قبلكم.","w":"السعدي","en":"Al-Sa'di: this is a general command to all people to a general matter, which is comprehensive worship, following Allah's commands, avoiding His prohibitions and believing His reports; He commands them to what He created them for, as He said 'I did not create jinn and humans except to worship Me'; then He gives proof for worshipping Him alone: He is your Lord who raised you with all kinds of favours, created you after non-existence and created those before you."}]},{"id":"quran","ch":"asbab","t":"القرآن: «قرآنا عربيا غير ذي عوج لعلهم يتقون»","e":"أن القرآن العربي المستقيم سبيل التقوى.","ay":[[39,28,28]],"q":[{"bk":"saadi","s":39,"ay":28,"x":"{قرآناً عَرَبِيًّا غير ذي عِوَجٍ}؛ أي: جعلناه قرآناً عَرَبِيًّا واضحَ الألفاظ سهلَ المعاني، خصوصاً على العرب، غير ذي عوجٍ؛ أي: ليس فيه خللٌ ولا نقصٌ بوجهٍ من الوجوه؛ لا في ألفاظه ولا في معانيه. وهذا يستلزمُ كمالَ اعتدالِهِ واستقامتِهِ؛ كما قال تعالى:{الحمدُ لله الذي أنزَلَ على عبدِهِ الكتابِ وَلَمۡ يَجۡعَلۡ له عِوَجاً. قَيِّماً}. {لعلَّهم يتَّقونَ} الله تعالى؛ حيث سهَّلْنا عليهم طُرُقَ التقوى العلميَّة والعمليَّة بهذا القرآن العربيِّ المستقيم، الذي ضَرَبَ الله فيه من كلِّ مَثَل.","w":"السعدي","en":"Al-Sa'di: 'an Arabic Quran, with no crookedness' means We made it an Arabic Quran with clear words and easy meanings, especially for the Arabs, with no crookedness, meaning no flaw or shortcoming in any way, in its wording or its meanings; this requires perfect balance and straightness, as He said 'Praise be to Allah who sent down the Book to His servant and placed no crookedness in it, straight'. 'That they may have taqwa' of Allah, since We made the paths of taqwa, in knowledge and in practice, easy for them through this straight Arabic Quran, in which Allah has struck every kind of parable."}]},{"id":"sadiqin","ch":"asbab","t":"«وكونوا مع الصادقين»","e":"الأمر بالتقوى وبمصاحبة الصادقين.","ay":[[9,119,119]],"q":[{"bk":"saadi","s":9,"ay":119,"x":"قوموا بما يقتضيه الإيمانُ، وهو القيام بتقوى الله تعالى؛ باجتناب ما نهى الله عنه والبعد عنه، {وكونوا مع الصَّادقينَ}: في أقوالهم وأفعالهم وأحوالهم، الذين أقوالهم صدقٌ، وأعمالهم وأحوالهم لا تكون إلا صدقاً، خليَّةً من الكسل والفتور، سالمة من المقاصد السيئة، مشتملة على الإخلاص والنيَّة الصالحة؛ فإنَّ الصدق يهدي إلى البرِّ، وإنَّ البرَّ يهدي إلى الجنة؛ قال تعالى:{هذا يومُ ينفَعُ الصادقين صِدۡقُهم ...","w":"السعدي","en":"Al-Sa'di: do what faith requires, which is to hold taqwa of Allah by avoiding what Allah forbade and keeping away from it, 'and be with the truthful' in their words, deeds and states, those whose words are true and whose deeds and states are only truthful, free of laziness and weariness, safe from bad intentions, containing sincerity and a good intention; for truthfulness guides to righteousness, and righteousness guides to Paradise; Allah said 'This is the day the truthful will benefit from their truthfulness' …"}]},{"id":"sabr","ch":"asbab","t":"«إنه من يتق ويصبر»","e":"اقتران التقوى بالصبر وأنهما سبب التمكين.","ay":[[12,90,90]],"q":[{"bk":"saadi","s":12,"ay":90,"x":"فعرفوا أن الذي خاطبهم هو يوسفُ، فقالوا:{أإنَّك لأنت يوسفُ قال أنا يوسفُ وهذا أخي قد منَّ الله علينا}: بالإيمان والتقوى والتمكين في الدُّنيا، وذلك بسبب الصبر والتقوى، فَـ {إنَّه من يتَّقِ ويَصۡبِرۡ}؛ أي: يتَّقي فعل ما حرَّم الله ويصبر على الآلام والمصائب وعلى الأوامر بامتثالها.","w":"السعدي","en":"Al-Sa'di: they knew that the one speaking to them was Yusuf, and said 'Are you really Yusuf?' He said 'I am Yusuf, and this is my brother; Allah has been gracious to us', with faith, taqwa and being established in the world, and that because of patience and taqwa; 'whoever fears Allah and is patient', meaning guards against doing what Allah forbade and is patient through pains and misfortunes and in carrying out commands."}]},{"id":"muhasaba","ch":"asbab","t":"«ولتنظر نفس ما قدمت لغد»: محاسبة النفس","e":"الأمر بالتقوى مع النظر فيما قدّمته النفس لغد.","ay":[[59,18,18]],"q":[{"bk":"saadi","s":59,"ay":18,"x":"وهذه الآية الكريمةُ أصلٌ في محاسبة العبد نفسَه، وأنَّه ينبغي له أن يتفقَّدها؛ فإنْ رأى زللاً؛ تداركه بالإقلاع عنه والتوبة النصوح والإعراض عن الأسباب الموصلة إليه، وإن رأى نفسه مقصراً في أمر من أوامر الله؛ بذل جهدَه واستعانَ بربِّه في تتميمه وتكميله وإتقانه، ويقايس بين منن الله عليه وإحسانه وبين تقصيرِهِ؛ فإن ذلك يوجب له الحياء لا محالة.","w":"السعدي","en":"Al-Sa'di: this verse is a basis for a servant's reckoning with himself: he should check on his soul; if he sees a slip, he should make it right by stopping it, sincere repentance and turning from the means to it; if he sees himself falling short in one of Allah's commands, he should spend his effort and seek help from his Lord to complete and perfect it; and he should compare Allah's favours and kindness to him with his own shortcoming, for that surely brings him shame."}]},{"id":"adl","ch":"asbab","t":"العدل والعفو أقرب للتقوى","e":"أن العدل والعفو أقرب للتقوى.","ay":[[5,8,8],[2,237,237]],"q":[{"bk":"saadi","s":5,"ay":8,"x":"أي: كلما حرصتم على العدل واجتهدتم في العمل به؛ كان ذلك أقرب لتقوى قلوبكم؛ فإن تمَّ العدل؛ كملت التقوى، {إنَّ الله خبيرٌ بما تعملونَ}؛ فمجازيكم بأعمالكم خيرِها وشرِّها صغيرِها وكبيرِها جزاءً عاجلاً وآجلاً.","w":"السعدي","en":"Al-Sa'di: meaning the more you take care to be just and strive to act justly, the nearer that is to the taqwa of your hearts; if justice is complete, taqwa is complete; 'Allah is aware of what you do', so He will repay you for your deeds, good and bad, small and great, in this world and the next."},{"bk":"saadi","s":2,"ay":237,"x":"ثم رغب في العفو وأن من عفا كان أقرب لتقواه لكونه إحساناً موجباً لشرح الصدر …","w":"السعدي","en":"Al-Sa'di: then He encourages pardon, and that whoever pardons is nearer to taqwa, since it is doing good that brings the chest relief …"}]},{"id":"anfal","ch":"mumin","t":"«إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم»","e":"وصف المؤمنين الصادقين بوجل القلوب وزيادة الإيمان والتوكل والصلاة والإنفاق.","ay":[[8,2,4]],"q":[{"bk":"saadi","s":8,"ay":2,"x":"ولما كان الإيمانُ قسمين: إيماناً كاملاً يترتَّب عليه المدح والثناء والفوزُ التامُّ، وإيماناً دون ذلك؛ ذَكَرَ الإيمانَ الكامل، فقال:{إنما المؤمنون}: الألف واللام للاستغراق لشرائع الإيمان، {الذين إذا ذُكِرَ اللهُ وَجِلَتۡ قلوبُهم}؛ أي: خافت ورهبت فأوجبت لهم خشية الله تعالى الانكفافَ عن المحارم؛ فإنَّ خوف الله تعالى أكبر علاماته أن يَحْجُزَ صاحبَه عن الذنوب.","w":"السعدي","en":"Al-Sa'di: since faith has two kinds, complete faith that brings praise and full success, and lesser faith, He mentions the complete one: 'the believers are only those', where the definite article covers all the laws of faith, 'whose hearts tremble when Allah is mentioned', meaning they feel fear and awe, which leads them through fear of Allah to restrain themselves from the forbidden; for the clearest sign of fear of Allah is that it holds its owner back from sins."}]},{"id":"muminun","ch":"mumin","t":"«قد أفلح المؤمنون»: الخشوع والإعراض عن اللغو والأمانة","e":"صفات المؤمنين المفلحين: الخشوع والإعراض عن اللغو والزكاة وحفظ الفرج والأمانة والمحافظة على الصلاة.","ay":[[23,1,11]],"q":[{"bk":"saadi","s":23,"ay":1,"x":"فقوله: {قد أفلح المؤمنونَ}؛ أي: قد فازوا وسَعِدوا ونجحوا، وأدركوا كلَّ ما يرام، المؤمنون الذين آمنوا بالله، وصدَّقوا المرسلين.","w":"السعدي","en":"Al-Sa'di: His words 'successful indeed are the believers' mean they have succeeded, been happy, and prospered, and reached all they wish; they are the believers who believed in Allah and affirmed the messengers."},{"bk":"saadi","s":23,"ay":2,"x":"الذين من صفاتهم الكاملة أنهم {في صلاتهم خاشِعونَ}: والخشوع في الصلاة هو حضورُ القلب بين يدي الله تعالى، مستحضراً لقربه، فيسكن لذلك قلبه، وتطمئن نفسه، وتسكن حركاتُه، ويقلُّ التفاتُه …","w":"السعدي","en":"Al-Sa'di: those whose complete qualities include being 'humble in their prayer'; humility in prayer is presence of heart before Allah, aware of His nearness, so the heart is still, the soul at ease, the limbs calm and turning about is rare, acting with courtesy before one's Lord, aware of all one says and does in prayer from its start to its end, so that whispers and bad thoughts go away …"}]},{"id":"hujurat","ch":"mumin","t":"«إنما المؤمنون الذين آمنوا… ثم لم يرتابوا»","e":"تحديد الإيمان الحق بعدم الريب والجهاد بالمال والنفس.","ay":[[49,15,15]],"q":[{"bk":"saadi","s":49,"ay":15,"x":"{إنَّما المؤمنون}؛ أي: على الحقيقة، {الذين آمنوا بالله ورسولِهِ وجاهدوا في سبيلِ اللهِ}؛ أي: من جمعوا بينَ الإيمان بالله ورسولِهِ والجهادِ في سبيله؛ فإنَّ مَن جاهدَ الكفارَ؛ دلَّ ذلك على الإيمان التامِّ في قلبِهِ؛ لأنَّ من جاهد غيره على الإسلام والإيمان والقيام بشرائعه؛ فجهاده لنفسه على ذلك من باب أولى وأحرى، ولأنَّ من لم يقوَ على الجهاد؛ فإنَّ ذلك دليلٌ على ضعف إيمانه …","w":"السعدي","en":"Al-Sa'di: 'the believers are only those', truly, 'who believe in Allah and His Messenger and strive in the cause of Allah', meaning those who combine belief in Allah and His Messenger with striving in His way; whoever fights the disbelievers shows complete faith in his heart, for whoever strives against others for Islam and faith and keeping its laws, striving against his own self for that is more fitting; and whoever has no strength to strive shows weakness in faith …"}]},{"id":"tawba","ch":"mumin","t":"المؤمنون بعضهم أولياء بعض","e":"أن المؤمنين والمؤمنات بعضهم أولياء بعض وصفاتهم في الأمر والنهي والصلاة والزكاة.","ay":[[9,71,71]],"q":[{"bk":"saadi","s":9,"ay":71,"x":"لما ذكر أنَّ المنافقين بعضهم من بعض ؛ ذكر أن المؤمنين بعضهم أولياء بعض، ووصفهم بضدِّ ما وصف به المنافقين، فقال:{والمؤمنون والمؤمناتُ}؛ أي: ذكورهم وإناثهم، {بعضُهم أولياءُ بعضٍ}: في المحبَّة والموالاة والانتماء والنُّصرة. {يأمرون بالمعروف}: وهو اسمٌ جامعٌ لكلِّ ما عُرِف حسنه من العقائد الحسنة والأعمال الصالحة والأخلاق الفاضلة، وأول مَن يدخُلُ في أمرهم أنفسُهم.","w":"السعدي","en":"Al-Sa'di: after mentioning that the hypocrites are one from another, He mentions that the believers are allies of one another and describes them with the opposite of the hypocrites' description: 'the believing men and women', males and females, 'are allies of one another' in love, support, belonging and help; 'they enjoin the good', which is a comprehensive name for every belief, deed and moral known to be good, and the first to enter into what they enjoin are themselves."}]},{"id":"ibadrahman","ch":"mumin","t":"عباد الرحمن","e":"وصف عباد الرحمن بالتواضع والقيام والإنفاق المعتدل واجتناب الشرك والقتل والزنا والتوبة.","ay":[[25,63,68]],"q":[{"bk":"saadi","s":25,"ay":63,"x":"العبوديَّةُ لله نوعان: عبوديَّةٌ لربوبيَّتِهِ؛ فهذه يشتركُ فيها سائرُ الخلق؛ مسلمهُم وكافرُهم، بَرُّهم وفاجِرُهم؛ فكلُّهم عبيدٌ لله مربوبون مدبرون، {إن كُلُّ مَنۡ في السمواتِ والأرضِ إلاَّ آتي الرحمنِ عَبۡداً}. وعبوديَّةٌ لألوهيَّتِهِ وعبادتِهِ ورحمتِهِ، وهي عبوديَّةُ أنبيائِهِ وأوليائِهِ، وهي المراد هنا، ولهذا أضافها إلى اسمه الرحمن؛ إشارةً إلى أنَّهم إنَّما وصلوا إلى هذه الحال بسبب رحمته، فَذَكَرَ [أنَّ] صفاتِهِم أكملُ الصفات ونعوتَهم أفضلُ النعوتِ، فوصَفَهم بأنَّهم {يَمۡشونَ على الأرضِ هَوۡناً}؛ أي: ساكنين متواضعين لله وللخَلْق؛ فهذا وصفٌ لهم بالوقارِ والسَّكينةِ والتَّواضُع لله ولعبادِهِ، {وإذا خاطَبَهُمُ الجاهلونَ}؛ أي: خطابَ جهل؛ بدليل إضافةِ الفعل وإسناده لهذا الوصفِ، {قالوا سلاماً}؛ أي: خاطَبوهم خطاباً يَسْلمونَ فيه من الإثم، ويَسْلَمونَ من مقابلة الجاهل بجهلِهِ …","w":"السعدي","en":"Al-Sa'di: servitude to Allah is of two kinds: servitude to His lordship, in which all creation shares, Muslim and disbeliever, righteous and sinner, for all are servants of Allah, owned and managed; and servitude to His divinity, worship and mercy, which is the servitude of His prophets and friends, and that is what is meant here, so He added it to His name the Most Merciful, hinting that they reached this state only through His mercy; so He mentions that their qualities are the most perfect and their descriptions the best: they 'walk on the earth gently', meaning calmly and humbly toward Allah and people, with dignity and tranquillity; 'and when the ignorant address them', in ignorant speech, 'they say: peace', speaking so that they are safe from sin and safe from answering the ignorant with ignorance …"}]},{"id":"ahzab","ch":"mumin","t":"«إن المسلمين والمسلمات والمؤمنين والمؤمنات»","e":"عشر صفات للمسلمين والمؤمنين رجالاً ونساءً ووعدهم بالمغفرة والأجر العظيم.","ay":[[33,35,35]],"q":[{"bk":"saadi","s":33,"ay":35,"x":"لما ذَكَرَ تعالى ثوابَ زوجاتِ الرسول - صلى الله عليه وسلم - وعقابهنَّ لو قُدِّرَ عدم الامتثال وأنَّه ليس مثلهنَّ أحدٌ من النساء؛ ذكر بقيَّة النساء غيرهنَّ، ولما كان حكمهنَّ والرجال واحداً؛ جعل الحكمَ مشتركاً، فقال:{إنَّ المسلمينَ والمسلماتِ}: وهذا في الشرائع الظاهرة إذا كانوا قائمين بها، {والمؤمنينَ والمؤمناتِ}: وهذا في الأمور الباطنة من عقائد القلب وأعماله، {والقانتينَ}؛ أي: المطيعين لله ولرسوله، {والقانتاتِ والصادقينَ}: في مقالهم وفعالهم، {والصادقاتِ والصابرينَ}: على الشدائد والمصائب …","w":"السعدي","en":"Al-Sa'di: after mentioning the Prophet's wives' reward and punishment, He mentions the rest of the women, and since their ruling and that of men is one, He made the ruling shared: 'the Muslim men and women', in the outward laws when they keep them, 'the believing men and women', in the inner matters of heart beliefs and deeds, 'the obedient', obeying Allah and His Messenger, 'the truthful', in their speech and deeds, 'the patient', in hardships and calamities …"}]},{"id":"maarij","ch":"mumin","t":"«إلا المصلين»: المحافظون على صلاتهم","e":"استثناء المصلين من هلع الإنسان وذكر أوصافهم.","ay":[[70,22,25]],"q":[{"bk":"saadi","s":70,"ay":22,"x":"{إلاَّ المصلِّين}: الموصوفين بتلك الأوصاف؛ فإنَّهم إذا مسَّهم الخير؛ شكروا الله وأنفقوا مما خوَّلهم [الله]، وإذا مسَّهم الشرُّ؛ صبروا واحتسبوا.","w":"السعدي","en":"Al-Sa'di: 'except those who pray', those described with those qualities, for when good touches them they thank Allah and spend of what He gave them, and when harm touches them they are patient and seek reward."}]},{"id":"sajda","ch":"mumin","t":"«تتجافى جنوبهم عن المضاجع»","e":"وصف المؤمنين بالتجافي عن المضاجع ودعاء ربهم خوفاً وطمعاً والإنفاق.","ay":[[32,15,16]],"q":[{"bk":"saadi","s":32,"ay":16,"x":"{تتجافى جُنوبهم عن المضاجِع}؛ أي: ترتفع جنوبُهم وتنزعجُ عن مضاجِعِها اللذيذِة إلى ما هو ألذُّ عندهم منه وأحبُّ إليهم، وهو الصلاة في الليل ومناجاة الله تعالى، ولهذا قال:{يَدۡعون ربَّهم}؛ أي: في جلب مصالِحِهم الدينيَّة والدنيويَّة ودفع مضارِّهما {خوفاً وطمعاً}؛ أي: جامعين بين الوصفينِ؛ خوفاً أن تُرَدَّ أعمالُهم، وطمعاً في قبولها؛ خوفاً من عذاب الله، وطمعاً في ثوابه …","w":"السعدي","en":"Al-Sa'di: 'their sides forsake their beds' means their sides rise and are unsettled from their pleasant beds toward what is sweeter and dearer to them, praying at night and conversing with Allah; so He said 'they call on their Lord', for their religious and worldly benefits and to ward off harms, 'in fear and hope', combining both, fearing their deeds be rejected and hoping they be accepted, fearing Allah's punishment and hoping for His reward …"}]},{"id":"raad","ch":"mumin","t":"أولو الألباب: «الذين يوفون بعهد الله»","e":"وصف أولي الألباب بالوفاء بعهد الله والصبر والإنفاق ودفع السيئة بالحسنة.","ay":[[13,19,22]],"q":[{"bk":"saadi","s":13,"ay":19,"x":"فإن سألتَ عن وصفِهم؛ فلا تجدُ أحسن من وصف الله لهم بقوله:{الذين يُوفونَ بعهدِ اللهِ}: الذي عَهِدَهُ إليهم والذي عاهدهم عليه من القيام بحقوقه كاملة موفرة؛ فالوفاء بها توفيتها حقَّها من التتميم لها والنصح فيها، ومن تمام الوفاء بها أنَّهم {لا ينقُضون الميثاقَ}؛ أي: العهد الذي عاهدوا الله عليه، فدخل في ذلك جميع المواثيق والعهود والأيمان والنُّذور التي يعقِدُها العباد، فلا يكون العبد من أولي الألباب الذين لهم الثواب العظيم إلا بأدائها كاملةً وعدم نقضها وبخسها.","w":"السعدي","en":"Al-Sa'di: if you ask about their description, you will find nothing better than Allah's description: 'those who fulfil Allah's covenant', which He made with them and which they covenanted with Him, of fulfilling His rights fully; to fulfil them is to give them their due completely and with sincerity; and part of fulfilling them is that they 'do not break the pledge', meaning the covenant they made with Allah, which includes all pledges, covenants, oaths and vows that servants make; so a servant is not among people of understanding who have the great reward unless he fulfils them completely and does not break or shortchange them."}]},{"id":"shura","ch":"mumin","t":"«وما عند الله خير وأبقى»","e":"زهد الذين آمنوا في متاع الدنيا، واجتنابهم الكبائر، وغفرانهم عند الغضب.","ay":[[42,36,39]],"q":[{"bk":"saadi","s":42,"ay":36,"x":"هذا تزهيدٌ في الدُّنيا وترغيبٌ في الآخرة وذكرُ الأعمال الموصلةِ إليها؛ فقال:{فما أوتيتم من شيءٍ}: من ملكٍ ورياسةٍ وأموال وبنينَ وصحَّةٍ وعافيةٍ بدنيَّةٍ، {فمتاعُ الحياةِ الدُّنيا}: لذَّةٌ منغصةٌ منقطعةٌ، {وما عندَ اللهِ}: من الثواب الجزيل والأجر الجليل والنعيم المقيم {خيرٌ} من لَذَّات الدُّنيا، خيريَّة لا نسبةَ بينهما {وأبقى}: لأنَّه نعيمٌ لا منغِّص فيه ولا كَدَرَ ولا انتقالَ.","w":"السعدي","en":"Al-Sa'di: this is detachment from the world and encouragement toward the Hereafter, with the deeds that lead to it; He says 'whatever you have been given', of kingship, rank, wealth, children and bodily health, 'is only the enjoyment of worldly life', a marred and fading pleasure, 'and what is with Allah', of ample reward, great recompense and lasting bliss, 'is better', with no comparison between them, 'and more lasting', because it is bliss with no disturbance, no dimness and no ending."},{"bk":"saadi","s":42,"ay":37,"x":"أي: قد تخلَّقوا بمكارم الأخلاق ومحاسن الشِّيم، فصار الحلم لهم سَجِيَّة وحسن الخلق لهم طبيعةً، حتى إذا أغضَبَهم أحدٌ بمقاله أو فعاله؛ كظموا ذلك الغضب، فلم يُنْفِذوه، بل غفروه، ولم يقابِلوا المسيءَ إلاَّ بالإحسان والعفو والصفح، فترتَّب على هذا العفو والصفح من المصالح ودفع المفاسد في أنفسهم وغيرهم شيءٌ كثير؛ كما قال تعالى:{ادفَعۡ بالتي هي أحسنُ فإذا الذي بينَكَ وبينَه عدواةٌ كأنَّه وليٌّ حميمٌ.","w":"السعدي","en":"Al-Sa'di: meaning they have taken on noble character and good manners until forbearance has become their nature and good conduct their disposition, so that when someone angers them by word or deed they swallow the anger and do not carry it out, but forgive it, answering the wrongdoer only with kindness, pardon and overlooking, and from that pardon and overlooking come many benefits and the warding off of harms in themselves and others, as He said 'repel evil with what is better, and the one between whom and you was enmity will be like a close friend'."}]}],"ay":{"8":"ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ","9":"ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","10":"وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ","11":"أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","27":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱعۡبُدُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُمۡ وَٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","185":"وَلَكُمۡ فِي ٱلۡقِصَاصِ حَيَوٰةٞ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ لَعَلَّكُمۡ تَتَّقُونَ","189":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","203":"ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ","243":"وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِيضَةٗ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّآ أَن يَعۡفُونَ أَوۡ يَعۡفُوَاْ ٱلَّذِي بِيَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُاْ ٱلۡفَضۡلَ بَيۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِيرٌ","288":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا تَدَايَنتُم بِدَيۡنٍ إِلَىٰٓ أَجَلٖ مُّسَمّٗى فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا يَأۡبَ كَاتِبٌ أَن يَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡيَكۡتُبۡ وَلۡيُمۡلِلِ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبۡخَسۡ مِنۡهُ شَيۡـٔٗاۚ فَإِن كَانَ ٱلَّذِي عَلَيۡهِ ٱلۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أَن يُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُواْ شَهِيدَيۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُلٞ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا يَأۡبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُواْۚ وَلَا تَسۡـَٔمُوٓاْ أَن تَكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَىٰٓ أَجَلِهِۦۚ ذَٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَٰدَةِ وَأَدۡنَىٰٓ أَلَّا تَرۡتَابُوٓاْ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةٗ تُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوٓاْ إِذَا تَبَايَعۡتُمۡۚ وَلَا يُضَآرَّ كَاتِبٞ وَلَا شَهِيدٞۚ وَإِن تَفۡعَلُواْ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُواْ ٱللَّهَۖ وَيُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","368":"بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُتَّقِينَ","394":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","412":"إِن تَمۡسَسۡكُمۡ حَسَنَةٞ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَيِّئَةٞ يَفۡرَحُواْ بِهَاۖ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ مُحِيطٞ","425":"۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ","426":"ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","427":"وَٱلَّذِينَ إِذَا فَعَلُواْ فَٰحِشَةً أَوۡ ظَلَمُوٓاْ أَنفُسَهُمۡ ذَكَرُواْ ٱللَّهَ فَٱسۡتَغۡفَرُواْ لِذُنُوبِهِمۡ وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ يُصِرُّواْ عَلَىٰ مَا فَعَلُواْ وَهُمۡ يَعۡلَمُونَ","428":"أُوْلَٰٓئِكَ جَزَآؤُهُم مَّغۡفِرَةٞ مِّن رَّبِّهِمۡ وَجَنَّٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ","623":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا","676":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","695":"۞ وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانٗا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ","979":"يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ","1049":"وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ","1081":"قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِينُواْ بِٱللَّهِ وَٱصۡبِرُوٓاْۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ","1161":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","1162":"ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","1163":"أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","1188":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","1305":"وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","1353":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّٰدِقِينَ","1425":"أَلَآ إِنَّ أَوۡلِيَآءَ ٱللَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","1426":"ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ","1427":"لَهُمُ ٱلۡبُشۡرَىٰ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۚ لَا تَبۡدِيلَ لِكَلِمَٰتِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","1685":"قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","1725":"۞ أَفَمَن يَعۡلَمُ أَنَّمَآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰٓۚ إِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ","1726":"ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ","1727":"وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ سُوٓءَ ٱلۡحِسَابِ","1728":"وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ","2028":"إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ","2626":"ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ","2631":"لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ","2673":"قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ","2674":"ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ","2675":"وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ","2676":"وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ","2677":"وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","2678":"إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","2679":"فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ","2680":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","2681":"وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ","2682":"أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ","2683":"ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ","2917":"وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا","2918":"وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدٗا وَقِيَٰمٗا","2919":"وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا","2920":"إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","2922":"وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا","3334":"تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ","3517":"إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩","3518":"تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","3567":"إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا","3602":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا","3603":"يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا","4085":"قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجٖ لَّعَلَّهُمۡ يَتَّقُونَ","4090":"وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","4307":"فَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰ لِلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","4308":"وَٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ","4309":"وَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","4310":"وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ","4614":"إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ","4624":"يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ","4626":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ","4689":"إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّٰتٖ وَعُيُونٍ","4690":"ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ","4691":"كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ","4692":"وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ","4693":"وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","5102":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَءَامِنُواْ بِرَسُولِهِۦ يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ وَيَجۡعَل لَّكُمۡ نُورٗا تَمۡشُونَ بِهِۦ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","5143":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","5214":"فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","5218":"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا","5219":"وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا","5220":"وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا","5221":"ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا","5396":"إِلَّا ٱلۡمُصَلِّينَ","5397":"ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ","5398":"وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ","5399":"لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ"},"nay":89,"nq":57};
